// ─── Process & Aggregate n8n Executions ───────────────────────────────────
// Pulls last 250 executions, filters to past 24 hours,
// groups by workflow name, calculates stats per workflow.

const data = $input.first().json.data || [];

// Calculate cutoff: exactly 24 hours ago
const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);

// Filter to last 24 hours only
const recent = data.filter(exec => {
  return exec.startedAt && new Date(exec.startedAt) >= cutoff;
});

// Group by workflow name
const byWorkflow = {};

for (const exec of recent) {
  // Safely get workflow name
  const name = (exec.workflowData && exec.workflowData.name)
    ? exec.workflowData.name
    : (exec.workflowId ? `Workflow ID: ${exec.workflowId}` : 'Unknown Workflow');

  if (!byWorkflow[name]) {
    byWorkflow[name] = {
      name,
      total: 0,
      success: 0,
      failed: 0,
      runtimes: []
    };
  }

  byWorkflow[name].total++;

  if (exec.status === 'success') {
    byWorkflow[name].success++;
  } else {
    byWorkflow[name].failed++;
  }

  // Calculate runtime in seconds (exclude zombie runs over 2 hours)
  if (exec.startedAt && exec.stoppedAt) {
    const runtime = (new Date(exec.stoppedAt) - new Date(exec.startedAt)) / 1000;
    if (runtime >= 0 && runtime < 7200) {
      byWorkflow[name].runtimes.push(runtime);
    }
  }
}

// Format today's date as YYYY-MM-DD
const today = new Date().toLocaleDateString('en-CA');

// Build one output item per workflow
const rows = Object.values(byWorkflow).map(wf => {
  const avgRuntime = wf.runtimes.length > 0
    ? parseFloat((wf.runtimes.reduce((a, b) => a + b, 0) / wf.runtimes.length).toFixed(1))
    : 0;

  const failureRate = wf.total > 0
    ? parseFloat(((wf.failed / wf.total) * 100).toFixed(1))
    : 0;

  return {
    json: {
      date: today,
      workflow_name: wf.name,
      total_runs: wf.total,
      successful: wf.success,
      failed: wf.failed,
      failure_rate: failureRate,
      avg_runtime: avgRuntime
    }
  };
});

// Handle case where no executions ran today
if (rows.length === 0) {
  return [{
    json: {
      date: today,
      workflow_name: 'NO EXECUTIONS TODAY',
      total_runs: 0,
      successful: 0,
      failed: 0,
      failure_rate: 0,
      avg_runtime: 0
    }
  }];
}

return rows;

// ─── Build Summary Row ────────────────────────────────────────────────────
// Receives all per-workflow rows, collapses into one daily summary.

const items = $input.all();

let totalRuns = 0;
let totalFailed = 0;
const workflowsWithErrors = [];

for (const item of items) {
  totalRuns += item.json.total_runs || 0;
  totalFailed += item.json.failed || 0;
  if ((item.json.failed || 0) > 0) {
    workflowsWithErrors.push(item.json.workflow_name);
  }
}

const overallRate = totalRuns > 0
  ? parseFloat(((totalFailed / totalRuns) * 100).toFixed(1))
  : 0;

const today = new Date().toLocaleDateString('en-CA');

return [{
  json: {
    date: today,
    total_runs: totalRuns,
    total_failed: totalFailed,
    overall_failure_rate: overallRate,
    workflows_with_errors: workflowsWithErrors.length > 0
      ? workflowsWithErrors.join(', ')
      : 'None — all healthy ✅'
  }
}];
